changeSet.sql:
CREATE TABLE network_configuration_bundles (
    bundle_id varchar(64) PRIMARY KEY, reset_id varchar(64) NOT NULL,
    catalog_prefix text NOT NULL, network_magic bigint NOT NULL, system_start text NOT NULL,
    manifest text NOT NULL, assets_json text NOT NULL, validation_state text NOT NULL,
    compatible_tool_evidence text
);
ALTER TABLE nodes ADD CONSTRAINT nodes_configuration_bundle_fk
    FOREIGN KEY (configuration_bundle_id) REFERENCES network_configuration_bundles(bundle_id);
ALTER TABLE nodes ADD COLUMN is_draft boolean NOT NULL DEFAULT false;
CREATE TABLE pool_draft_config (
    node_id bigint PRIMARY KEY REFERENCES nodes(id), request_json text NOT NULL,
    created_at timestamptz NOT NULL
);
CREATE TABLE pool_deployment_previews (
    id varchar(36) PRIMARY KEY, request_id varchar(36) NOT NULL UNIQUE,
    node_id bigint NOT NULL REFERENCES nodes(id), host_id bigint NOT NULL REFERENCES hosts(id),
    fingerprint varchar(64) NOT NULL, details text NOT NULL,
    state varchar(24) NOT NULL, created_at timestamp NOT NULL
);
CREATE UNIQUE INDEX pool_deployment_one_inflight ON pool_deployment_previews(node_id) WHERE state = 'installing';
CREATE TABLE node_configuration_snapshots (
    id varchar(36) PRIMARY KEY, node_id bigint NOT NULL REFERENCES nodes(id),
    bundle_id varchar(64) REFERENCES network_configuration_bundles(bundle_id), role text NOT NULL,
    assets_json text NOT NULL, effective_config_digest text, effective_topology_digest text,
    approved_overrides text NOT NULL, public_fingerprints text NOT NULL, installation_observation text
);
CREATE TABLE leios_voting_keys (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    network_key text NOT NULL, pool_id text NOT NULL,
    public_key bytea NOT NULL CHECK (octet_length(public_key) = 96),
    proof bytea NOT NULL CHECK (octet_length(proof) = 48),
    signing_file_id bigint REFERENCES files(id), prepared_at timestamptz NOT NULL,
    validation_provenance text NOT NULL
);
CREATE TABLE pool_key_observations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    network_key text NOT NULL, pool_id text NOT NULL, observed_at timestamptz NOT NULL,
    chain_slot numeric, chain_hash bytea,
    current_key_id bigint REFERENCES leios_voting_keys(id),
    future_key_id bigint REFERENCES leios_voting_keys(id),
    current_public_key bytea CHECK (current_public_key IS NULL OR octet_length(current_public_key) = 96),
    future_public_key bytea CHECK (future_public_key IS NULL OR octet_length(future_public_key) = 96),
    registration_epoch numeric, effective_epoch numeric(20,0), mark_epoch numeric, set_epoch numeric, scheduled_retirement numeric,
    eligible boolean, selected boolean, expired boolean
);
CREATE TABLE key_installations (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    key_id bigint NOT NULL REFERENCES leios_voting_keys(id),
    node_id bigint NOT NULL REFERENCES nodes(id), host_id bigint NOT NULL REFERENCES hosts(id),
    configuration_fingerprint text NOT NULL, installed_fingerprint text, loaded_fingerprint text,
    permission_result text, state text NOT NULL, observed_at timestamptz NOT NULL, sanitized_error text
);
CREATE TABLE leios_install_previews (
    id text PRIMARY KEY, request_id text NOT NULL UNIQUE,
    node_id bigint NOT NULL REFERENCES nodes(id), host_id bigint NOT NULL REFERENCES hosts(id),
    key_id bigint NOT NULL REFERENCES leios_voting_keys(id),
    configuration_fingerprint text NOT NULL, installed_fingerprint text,
    disruption text NOT NULL, created_at timestamptz NOT NULL, state text NOT NULL
);
CREATE TABLE network_reconfiguration_reviews (
    id varchar(36) PRIMARY KEY, source_node_id bigint NOT NULL REFERENCES nodes(id),
    source_host_id bigint NOT NULL REFERENCES hosts(id), target_host_id bigint NOT NULL REFERENCES hosts(id),
    prior_bundle_id varchar(64) NOT NULL REFERENCES network_configuration_bundles(bundle_id),
    prior_reset_id varchar(64) NOT NULL,
    target_bundle_id varchar(64) NOT NULL REFERENCES network_configuration_bundles(bundle_id),
    target_reset_id varchar(64) NOT NULL, request_fingerprint varchar(64) NOT NULL,
    source_fingerprint varchar(64) NOT NULL, target_host_fingerprint varchar(64) NOT NULL,
    reviewed_request text NOT NULL, consequences text NOT NULL, state text NOT NULL,
    created_at timestamptz NOT NULL, authorized_at timestamptz, consumed_at timestamptz
);
